RECORD = {
    "id": "JAH-NMM-000001",
    "name": "Suresh",
    "kind": "first-name",
    "meaning": "Suresh is a masculine given name in Marathi. Meaning: Ruler of gods. From Sanskrit sura + isha."
}
ARCHIVE = [RECORD]  # extend: load the full archive from index.jsonl.gz to search all records
def lookup(query):
    q = query.strip().lower()
    return [r for r in ARCHIVE if q in r['name'].lower() or q in r['meaning'].lower()]
if __name__ == '__main__':
    hits = lookup("Sur")
    for h in hits:
        print(h['id'], '|', h['name'], '|', h['meaning'])

